    exit: { type: "boolean", default: false },
  },
});

const fail = (message: string, code = 1): never => {
  console.error(message);
  process.exit(code);
};

if (!args.kit || !args.worktree || !args.marker) {
  fail("usage: cli.mjs --kit <kit.json> --worktree <discourse-graph worktree> --marker <string only this build has> [--pause step|case|failure|needed] [--pace 1] [--leave-out <case id>]... [--exit]");
}
const pause = isPauseSetting(args.pause) ? args.pause : fail(`--pause must be step, case, failure or needed, not ${args.pause}`);
const worktree = path.resolve(args.worktree!);
const kitPath = path.resolve(args.kit!);

// Fixtures a run here can't apply, each with the reason, so the result says so.
const usableFixtures = (fixtures: Fixture[]): { use: Fixture[]; skipped: Array<{ id: string; why: string }> } => {
  const use: Fixture[] = [];
  const skipped: Array<{ id: string; why: string }> = [];
  for (const fixture of fixtures) {
    const missing = envRefs(fixture).filter((name) => !process.env[name]);
    if (fixture.phase !== "in-session") skipped.push({ id: fixture.id, why: `${fixture.phase} fixtures need the proof database, which Obsidian runs don't start yet` });
    else if (missing.length) skipped.push({ id: fixture.id, why: `needs ${missing.join(", ")} in the environment` });
    else use.push(fixture);
  }
  return { use, skipped };
};

const stamp = (date: Date): string => date.toISOString().replace("T", " ").slice(0, 16);

const main = async (): Promise<void> => {
  const fullKit: Kit = validateKit(JSON.parse(await fs.readFile(kitPath, "utf8")));
  if (fullKit.target?.app && fullKit.target.app !== "obsidian") console.warn(`warn: kit targets ${fullKit.target.app}, running it in Obsidian anyway`);
  const kit = runnableKit(fullKit);
  const notRun = fullKit.cases.filter((item) => !kit.cases.includes(item));
  const { use, skipped } = usableFixtures(fullKit.prepare ?? []);
  const setup: Step[] = inSessionSteps(use);
  const commit = execFileSync("git", ["-C", worktree, "rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  const branch = execFileSync("git", ["-C", worktree, "rev-parse", "--abbrev-ref", "HEAD"], { encoding: "utf8" }).trim();
  const runStamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
  const outDir = path.resolve(args.out ?? path.join(worktree, "local", "proof-kit", branch.replace(/\//g, "-"), `${fullKit.name}-${runStamp}`));
  await fs.mkdir(outDir, { recursive: true });

  const { claim } = await import(VAULT_SCRIPT);
  const { launch } = await import(path.join(HARNESS, "launch.mjs"));
  const { deliver } = await import(path.join(HARNESS, "deliver.mjs"));
  const { releaseLock } = await import(path.join(HARNESS, "config.mjs"));
  const { listTargets } = await import(path.join(HARNESS, "driver.mjs"));

  const port = Number(args.port);
  if (args.slot === undefined) await claim({ worktree });
  const launched = await launch({ worktree, slot: args.slot, port });
  const { client, vault } = launched;
  let session: CdpSession | null = null;
  let exitCode = 0;
  try {
    console.log(`vault: ${vault.root}${vault.slot ? ` [slot ${vault.slot}]` : " [leased]"} (${launched.action})`);
    const delivered = await deliver({ worktree, vault, client, marker: args.marker, skipBuild: args["skip-build"] });
    for (const watcher of delivered.watchers) console.warn(`warn: competing watcher ${watcher}`);
    console.log(`build: ${branch} @ ${commit.slice(0, 7)} delivered, marker found`);

    // Our own session on the vault's page, for the binding the bar's buttons call.
    const { targetInfo } = await client.send("Target.getTargetInfo");
    const target = (await listTargets(port)).find((item: { id: string }) => item.id === targetInfo.targetId);
    if (!target) throw new Error("The vault's page target went away after the build was delivered.");
    session = await openSession(target.webSocketDebuggerUrl);
    const live = session;
    await live.send("Runtime.enable");
    await live.send("Runtime.addBinding", { name: "__proofCmd" });
    const hudScript = await fs.readFile(HUD_BUNDLE, "utf8");
    const inject = async (): Promise<void> => {
      await evaluateIn(live, "delete window.proof", "none");
      await evaluateIn(live, HELPERS_INIT_SCRIPT, "none");
      await evaluateIn(live, hudScript, "none");
    };
    await inject();

    // PROOF_VAULT lets a kit write obsidian:// links into the vault the runner leased.
    const context: TemplateContext = { env: { ...process.env, PROOF_VAULT: vault.name }, kit: fullKit.name, run: runStamp };
    let speed = Number(args.pace);
    let current: PauseSetting = pause;
    let state: MachineState | null = null;
    let startedAt = Date.now();
    let endedAt: number | null = null;
    const handled = new WeakSet<object>();
    const tries = new Map<string, number>();
    const journal = new Journal((event) => {
      void fs.appendFile(path.join(outDir, "journal.jsonl"), `${JSON.stringify(event)}\n`);
    });

    const facts = (): RunFacts => {
      const steps: Record<string, string[]> = {};
      for (const item of kit.cases) steps[item.id] = item.steps.map((step) => step.why);
      return {
        title: fullKit.title ?? fullKit.name,
        pr: fullKit.target?.pr ?? null,
        ticket: fullKit.ticket ?? /\beng-\d+\b/i.exec(fullKit.name)?.[0]?.toUpperCase() ?? null,
        page: path.relative(process.cwd(), kitPath).startsWith("..") ? kitPath : path.relative(process.cwd(), kitPath),
        build: `${branch} @ ${commit.slice(0, 7)}`,
        latest: null,
        when: stamp(new Date(startedAt)),
        how: `${runWords(current, state?.speed ?? speed)} in Obsidian (${vault.name})`,
        steps,
      };
    };
    const kinds = (): Record<string, StepKind[]> => {
      const map: Record<string, StepKind[]> = { setup: setup.map(kindOfStep) };
      for (const item of kit.cases) map[item.id] = item.steps.map(kindOfStep);
      return map;
    };
    const model = (next: MachineState): BarModel => ({
      title: fullKit.title ?? fullKit.name,
      state: next,
      kinds: kinds(),
      msPerStep: 1500 / Math.max(0.25, next.speed),
      facts: facts(),
      notTested: notRun.length,
      stepUid: null,
      pause: current,
      pointer: "ring",
      scope: "all",
      rerun: next.plan.filter((item) => next.results[item.id] !== "pass").length,
      agent: false,
      startedAt,
      endedAt,
      history: {},
    });
    const paint = async (next: MachineState): Promise<void> => {
      state = next;
      await evaluateIn(live, `window.__proofHud && window.__proofHud.update(${JSON.stringify(model(next))})`, "none").catch(() => undefined);
    };

    let machine: Machine;
    // Only when needed: a failed check is recorded and the run goes on; a step
    // that doesn't work is tried once more, then its case couldn't be tested.
    const unattended = (next: MachineState): void => {
      const pending = next.pending;
      if (!playFor(current).unattended || !pending || handled.has(pending)) return;
      handled.add(pending);
      if (pending.kind === "check-failed") {
        setTimeout(() => state?.pending === pending && machine.command("socket", "continue"), 300);
      } else if (pending.kind === "failure") {
        const key = `${pending.caseId}/${pending.stepId}`;
        const count = tries.get(key) ?? 0;
        tries.set(key, count + 1);
        // Setup has no case to skip: a second failure there ends the run.
        const next = count === 0 ? "retry" : pending.caseId === null ? "stop" : "skip-case";
        setTimeout(() => state?.pending === pending && machine.command("socket", next), 600);
      }
    };

    const executor = makeCdpExecutor({
      session: live,
      timeout: STEP_TIMEOUT_MS,
      fill: (value) => fillDeep(value, context),
      render: async (next) => {
        await paint(next);
        unattended(next);
      },
      note: (text) => machine.command("socket", "note", { text }),
      lead: () => LEAD_MS / Math.max(0.25, state?.speed ?? speed),
      screenshotDir: path.join(outDir, "screenshots"),
    });

    const start = (only?: string[]): Machine => {
      const play = playFor(current);
      startedAt = Date.now();
      endedAt = null;
      const leaveOut = only ? kit.cases.map((item) => item.id).filter((id) => !only.includes(id)) : args["leave-out"];
      return new Machine({
        kit,
        setup,
        journal,
        executor,
        mode: play.mode,
        speed,
        dwellMs: DWELL_MS,
        holdOnCheckFail: play.holdOnCheckFail,
        expand: makeExpander(new Map()),
        leaveOut,
        leaveOutWhy: only ? "passed in the run before" : (args["leave-out-why"] ?? (leaveOut.length ? "left out from the command line" : undefined)),
      });
    };

    let closed: () => void = () => undefined;
    const closedOnce = new Promise<void>((resolve) => {
      closed = resolve;
    });
    let restart: ((only?: string[]) => void) | null = null;

    const fromBar = (action: BarAction): string | null => {
      if (action.kind === "closed") {
        if (state && ["done", "stopped"].includes(state.phase)) closed();
        return null;
      }
      if (action.kind === "run" || action.kind === "rerun") {
        const only = action.kind === "rerun" && state ? state.plan.filter((item) => state!.results[item.id] !== "pass").map((item) => item.id) : undefined;
        restart?.(only);
        return null;
      }
      if (action.kind === "setting") {
        if (action.key === "pace") {
          speed = action.value;
          return errorOf(machine.command("hud", "speed", { speed: action.value }));
        }
        if (action.key === "pause") {
          current = action.value;
          const play = playFor(action.value);
          return errorOf(machine.command("hud", "mode", { mode: play.mode })) ?? errorOf(machine.command("hud", "hold-on-fail", { on: play.holdOnCheckFail }));
        }
        return null;
      }
      if (action.kind === "done-by-hand") {
        const pending = state?.pending;
        if (pending?.kind !== "steps") return "No case is waiting to be done by hand.";
        return errorOf(machine.command("hud", "steps", { caseId: pending.caseId, steps: [{ why: "done by hand", do: { pause: 0 } }] }));
      }
      if (action.kind === "add-case") {
        const taken = new Set(machine.kit.cases.map((item) => item.id));
        const testCase = newCase(action, taken);
        void fs.appendFile(path.join(outDir, "added-cases.jsonl"), `${JSON.stringify({ ...testCase, decision: { status: "proposed", by: os.userInfo().username, at: stamp(new Date()) } })}\n`);
        return errorOf(machine.command("hud", "add-case", { case: testCase }));
      }
      if (action.kind === "command") return errorOf(machine.command("hud", action.cmd, action.args ?? {}));
      return "Not in Obsidian runs yet: edit the kit file and run again.";
    };
    const errorOf = (result: { ok: boolean; error?: string }): string | null => (result.ok ? null : (result.error ?? "failed"));

    live.on("Runtime.bindingCalled", (params) => {
      if (params.name !== "__proofCmd") return;
      const error = fromBar(JSON.parse(String(params.payload)) as BarAction);
      if (error) void evaluateIn(live, `window.__proofHud && window.__proofHud.showError(${JSON.stringify(error)})`, "none").catch(() => undefined);
    });
    // A reload (or a plugin that reloads the window) drops the page half: put it back.
    live.on("Runtime.executionContextCreated", (params) => {
      const context = params.context as { auxData?: { isDefault?: boolean } };
      if (!context.auxData?.isDefault) return;
      setTimeout(() => {
        void inject().then(() => state && paint(state));
      }, 500);
    });

    for (const item of skipped) console.log(`skip fixture ${item.id}: ${item.why}`);
    for (const item of notRun) console.log(`not run: ${item.id} (${item.decision?.status ?? "approved"})`);
    console.log(`run: ${kit.cases.length} case(s), pause ${current}, pace ${speed}×. The caption bar in Obsidian has the controls.`);

    const runOnce = async (only?: string[]): Promise<void> => {
      machine = start(only);
      state = machine.state();
      await paint(state);
      await machine.run();
      endedAt = Date.now();
      const final = machine.state();
      await paint(final);
      const result = resultMarkdown(final, facts(), notRun.length);
      const skippedLines = skipped.map((item) => `- Fixture \`${item.id}\` not applied: ${item.why}`).join("\n");
      await fs.writeFile(path.join(outDir, "result.md"), skippedLines ? `${result}\n\n${skippedLines}\n` : `${result}\n`);
      await fs.writeFile(path.join(outDir, "kit-report.md"), `${kitReport(final, facts())}\n`);
      await fs.writeFile(path.join(outDir, "records.json"), `${JSON.stringify(machine.caseRecords, null, 2)}\n`);
      await evaluateIn(live, "window.__proofHud && window.__proofHud.openResult()", "none").catch(() => undefined);
      const failed = final.plan.filter((item) => final.results[item.id] !== "pass").length;
      exitCode = failed ? 1 : 0;
      console.log(`\n${result}\n\nresult: ${path.join(outDir, "result.md")}`);
      if (executor.screenshots.length) console.log(`screenshots:\n${executor.screenshots.map((file) => `  ${file}`).join("\n")}`);
    };

    // Node's WebSocket doesn't hold the event loop: keep it open while the machine waits on a person.
    const keepAlive = setInterval(() => undefined, 60_000);
    let running = runOnce();
    restart = (only) => {
      machine.stop();
      running = running.then(() => runOnce(only));
    };
    await running;
    if (!args.exit) {
      console.log("Close the result in Obsidian (or Ctrl+C) to end. Run again and Rerun work from the bar.");
      await Promise.race([closedOnce, new Promise<void>((resolve) => process.once("SIGINT", () => resolve()))]);
      await running;
    }
    clearInterval(keepAlive);
  } finally {
    if (session) {
      await evaluateIn(session, "window.__proofHud && window.__proofHud.dispose(); delete window.__proofHud", "none").catch(() => undefined);
      session.close();
    }
    client.close();
    releaseLock(vault.lockFile);
  }
  process.exit(exitCode);
};

main().catch((error: unknown) => {
  const typed = error as { message?: string; exitCode?: number; candidates?: unknown };
  console.error(typed.message ?? String(error));
  if (typed.candidates) console.log(JSON.stringify({ candidates: typed.candidates }, null, 2));
  process.exit(typed.exitCode ?? 1);
});

import type { Action } from "./action";
import { validatePublishSpec, type PublishSpec } from "./publish";

// A proof kit is everything one PR's proof needs, written out ahead: what must
// be running, the data to prepare (each piece with a check, so prepared data
// is skipped), the cases, and the captions for the video. It is JSON because
// a live rehearsal writes it back.

export type StepSource = "kit" | "model" | "you";

// A step either does one action or uses a recipe from proof/recipes.
export type Step = {
  id: string;
  why: string;
  do?: Action;
  use?: string;
  with?: Record<string, unknown>;
  source?: StepSource;
  approved?: boolean;
};

export type Verdict = "pass" | "fail" | "skip";

export type Expectation = { js?: string; text?: string };

export type CaseResult = {
  verdict: Verdict;
  at: string;
  session: string;
  note?: string;
};

// Whether a case runs. qa.ts proposes cases from the PR's diff; a person
// approves or rejects each one, and a rejected case stays in the kit with its
// reason, so the record shows what was left out and why. A case with no
// decision was written into the kit by hand and counts as approved.
export type DecisionStatus = "proposed" | "approved" | "rejected";

export type CaseDecision = {
  status: DecisionStatus;
  // Who proposed or decided it: the model for a proposal, a person's name for
  // a decision.
  by?: string;
  at?: string;
  // Why it was rejected (required) or approved (optional).
  reason?: string;
};

// An area next to the change that it could break, beyond the PR's own Done
// When, with the files that tie it to the diff.
export type SurfaceArea = {
  id: string;
  area: string;
  why: string;
  files?: string[];
};

export type TestCase = {
  id: string;
  title: string;
  // What this case proves, in plain words, e.g. which Done When it covers.
  proves?: string;
  // What its expect.js checks, in plain words, for the live panel.
  checks?: string;
  intent?: string;
  // The narration line for this case in a take. One to three plain sentences.
  caption?: string;
  // A short top-right flash at the start of the case in a take.
  toast?: string;
  steps: Step[];
  expect?: Expectation;
  notes?: string[];
  last?: CaseResult;
  decision?: CaseDecision;
  // The id of the surface area this case covers.
  surface?: string;
};

export type KitTarget = {
  // roam (the default) records Chromium on a Roam graph; obsidian attaches
  // over CDP to an Obsidian you started with remote debugging on the vault.
  app?: "roam" | "obsidian";
  cdp?: string;
  vault?: string;
  slot?: "1" | "2" | "3";
  url?: string;
  dist?: string;
  pr?: number;
  viewport?: { width: number; height: number };
  dpr?: number;
};

// "supabase", "embed-stub" and "env:NAME" are built in. A custom need runs a
// shell check and prints its fix when the check fails.
export type Need =
  | string
  | { id: string; why: string; check: string; fix: string };

export type FixturePhase = "before-load" | "in-session" | "outside";

export type RestProbe = { path: string; expect: "rows" | "none" };
export type RestWrite = {
  method: "POST" | "PATCH" | "DELETE";
  path: string;
  body?: unknown;
};

export type Probe = { js: string } | { command: string } | { rest: RestProbe };

export type Apply =
  | { js: string }
  | { steps: Step[] }
  | { command: string }
  | { rest: RestWrite }
  | { sql: string }
  | { publish: PublishSpec };

export type Fixture = {
  id: string;
  why: string;
  // before-load: flags and node types, which the extension reads once at load.
  // in-session: pages and settings, after the extension loads.
  // outside: database rows and anything else done from the shell.
  phase: FixturePhase;
  // Without a check the fixture always runs (settings Roam resets each load).
  check?: Probe;
  apply: Apply;
  // How long to let Roam sync a before-load write before the session closes.
  settleMs?: number;
};

export type Kit = {
  name: string;
  title?: string;
  // The Linear ticket whose Done When the cases cover, e.g. ENG-2348. When
  // it's left out, prove.ts reads it from the kit's name or the PR's branch.
  ticket?: string;
  // The one sentence the kit proves, and the state its setup leaves, both in
  // plain words. The live panel leads with them.
  claim?: string;
  given?: string;
  baseline?: string;
  target?: KitTarget;
  needs?: Need[];
  prepare?: Fixture[];
  // What the change could break beyond its Done When (qa.ts propose).
  surface?: SurfaceArea[];
  cases: TestCase[];
};

export type Baseline = {
  name: string;
  version: number;
  why?: string;
  prepare: Fixture[];
  smoke: TestCase[];
};

export const ACTION_KINDS = [
  "click",
  "type",
  "fill",
  "press",
  "hover",
  "scroll",
  "pause",
  "wait_for",
  "open",
  "js",
  "screenshot",
  "drag",
  "command_palette",
  "when",
] as const;

